/*body=html 자식 */
body{font-family: 'Pretendard',sans-serif;}
ul,li{
    margin: 0;
padding: 0;
list-style: none;
}

h1, h2, h3, h4, h5, h6, p{
    font-size: inherit; font-weight: normal; 
    margin: auto;}

button{
     margin: 0; padding: 0;
     border: 0; background: none;
     color: inherit;
}

/* component */
.con{
    width: 1050px;
    margin-left: auto;
    margin-right: auto;
    display: flex;
}

.top-banner{height: 42px;
background-color:#5F0080 ;
/* 글자 색상 */
color: #fff;
display: flex;
justify-content: center;
align-items: center;
font-size: 14px;
}
.utility-menu{
    /* 선 */
}
.utility-con{
 height: 35px;  
 justify-content: end; 
 align-items: center;   
}

.con>nav>ul {
    display: flex;
    gap: 12px;
    font-size: 12px;
    color: #333333;
}
.signup-link{
 color: #5F0080;}

.m-header-con{
    justify-content: space-between;
    align-items: center;
    padding-top: 12px;
    padding-bottom: 12px;
}
.brand{display: flex; gap: 20px;
align-items: center;
width: 250px;}
.brand-tabs{display: flex; gap: 22px;
font-size: 18px;
color:#B5B5B5}
.brand-tabs.active{
    color: #5F0080;
font-weight: 500;}

.search{
width: 400px; height: 48px;
box-sizing: border-box;
border: 1px solid #5F0080;
border-radius: 7px;
padding-left: 20px;
padding-right: 20px;
/* 태그 크기안에 padding과 선 크기 포함 */
box-sizing: border-box;
display: flex; align-items: center;
font-size: 16px;
color: #B5B5B5;}

.icon{
    width: 250px;
    display: flex;
    justify-content: flex-end;
gap: 40px;
}
/* id선택자 활용하여 아이콘 사이즈 키우기 */
#icon .location,
#icon .favorite,
#icon .shopping{
  font-size: 28px;
  cursor: pointer;
}
/* 마우스 올리면 색상 변경 */
#icon .location:hover,
#icon .favorite:hover,
#icon .shopping:hover{
    color: #5F0080;
}

.banner{
    background-color: gray;
    height: 370px;
}
.banner img{
    width: 100%; height: 100%;
    object-fit: cover;
}

.products{
    padding-top: 40px;
    padding-bottom: 40px;
}

.products-con{
    flex-direction: column;
}

.products-header{
    text-align: center;
}

.products-title{
    font-size: 28px; font-weight: 500;
    color:#333333;
    padding-bottom: 8px;
}

.products-desc{
    font-size: 16px;
    color: #999999;
}

.products-list{
    padding-top: 23px;
    display: flex; gap: 18px;
}

.products-card{
    /* background-color: gray; */
    flex-grow: 1; flex-basis: 0;
}

.products-image{
    border-radius: 4px;
    overflow: hidden;
}

.products-image img{
    width: 100%;
}

.products-add{
    padding-top: 6px;
    padding-bottom: 8px;
}

#add-btn .shopping{
    font-size: 20px;
}
.add-btn{
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px; color: #222;
    border: 1px solid #DFE4EB;
    height: 36px; width: 100%;
    border-radius: 4px;
}

.name{
    font-size: 16px;
    color: #333333;
}
.old-price{
    font-size: 14px;
    color: #BCC4CC;
    padding-top: 8px;
    padding-bottom: 7px;
}
.products-discount{
    font-size: 16px; font-weight: 700;
    color: #FA622F;
    padding-right: 8px;
}
.products-price{
    font-size: 16px; font-weight: 700;
    color: #222222;
}

